remaining_probes.source:
proc run()->void {
  val target:u64 <- 1u64;
  ptr selected:u64 = null;
  defer {selected = target;};
}
run();

using symbol "std:io" @print;
proc run(count:u64)->void {
  val first:u64 <- 1u64;
  val second:u64 <- 2u64;
  ptr selected = first;
  for(i in 0u64 .. count) {{defer {selected = second;};}};
  behave @print(selected);
}
run(3u64);

using symbol "std:io" @print;
proc run(count:u64)->void {
  val first:u64 <- 1u64;
  val second:u64 <- 2u64;
  ptr selected = first;
  for(i in 0u64 .. count) {{
    behave @print(selected);
    defer {selected = second;};
  }};
}
run(3u64);
